7	/// A triggered ability that has been collected but not yet resolved.
8	/// These are placed on pending_triggers in APNAP order, then resolved
9	/// LIFO (non-active player's triggers resolve first).
10	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
11	pub enum PendingTrigger {
12	    /// A creature's own "when this dies" trigger.
13	    SelfDies {
14	        dead_id: ObjectId,
15	        dead_card_id: CardId,
16	        controller: PlayerId,
17	        description: String,
18	    },
19	    /// A "whenever a creature dies" death-watch trigger on another permanent.
20	    DeathWatch {
21	        watcher_id: ObjectId,
22	        watcher_card_id: CardId,
23	        controller: PlayerId,
24	        dead_id: ObjectId,
25	        dead_controller: PlayerId,
26	        /// Last-known information captured before zone change clears battlefield state.
27	        dead_damaged_by: Vec<ObjectId>,
28	        dead_toughness: i32,
29	        description: String,
30	    },
31	    /// A creature entering the battlefield trigger.
32	    EnteredBattlefield {
33	        object_id: ObjectId,
34	        card_id: CardId,
35	        controller: PlayerId,
36	        description: String,
37	    },
38	    /// A "whenever a creature enters the battlefield" ETB-watch trigger on another permanent.
39	    EnterWatch {
40	        watcher_id: ObjectId,
41	        watcher_card_id: CardId,
42	        controller: PlayerId,
43	        entered_id: ObjectId,
44	        entered_controller: PlayerId,
45	        description: String,
46	    },
47	    /// A creature dealt combat damage to a player.
48	    CombatDamageToPlayer {
49	        creature_id: ObjectId,
50	        creature_card_id: CardId,
51	        controller: PlayerId,
52	        damaged_player: PlayerId,
53	        amount: u32,
54	        description: String,
55	    },
56	    /// A watcher observing another creature's combat damage to a player.
57	    CombatDamageWatch {
58	        watcher_id: ObjectId,
59	        watcher_card_id: CardId,
60	        controller: PlayerId,
61	        source_id: ObjectId,
62	        damaged_player: PlayerId,
63	        amount: u32,
64	        description: String,
65	    },
66	    /// A watcher observing any damage (combat or non-combat) to a player.
67	    DamageToPlayerWatch {
68	        watcher_id: ObjectId,
69	        watcher_card_id: CardId,
70	        controller: PlayerId,
71	        source_id: ObjectId,
72	        damaged_player: PlayerId,
73	        amount: u32,
74	        description: String,
75	    },
76	    /// A spell-cast watcher trigger.
77	    SpellCastWatch {
78	        watcher_id: ObjectId,
79	        watcher_card_id: CardId,
80	        controller: PlayerId,
81	        caster: PlayerId,
82	        spell_id: ObjectId,
83	        description: String,
84	    },
85	    /// An end-of-combat trigger on a permanent.
86	    EndCombatTrigger {
87	        object_id: ObjectId,
88	        card_id: CardId,
89	        controller: PlayerId,
90	        description: String,
91	    },
92	    /// An upkeep trigger on a permanent.
93	    UpkeepTrigger {
94	        object_id: ObjectId,
95	        card_id: CardId,
96	        controller: PlayerId,
97	        description: String,
98	    },
99	    /// An end-step trigger on a permanent.
100	    EndStepTrigger {
101	        object_id: ObjectId,
102	        card_id: CardId,
103	        controller: PlayerId,
104	        description: String,
105	    },
106	    /// A permanent leaving the battlefield trigger.
107	    LeftBattlefield {
108	        object_id: ObjectId,
109	        card_id: CardId,
110	        description: String,
111	    },
112	    /// A creature's "when this attacks" trigger.
113	    AttacksTrigger {
114	        object_id: ObjectId,
115	        card_id: CardId,
116	        controller: PlayerId,
117	        description: String,
118	    },
119	    /// A creature's "when this blocks" trigger.
120	    BlocksTrigger {
121	        object_id: ObjectId,
122	        card_id: CardId,
123	        controller: PlayerId,
124	        blocked_attacker: ObjectId,
125	        description: String,
126	    },
127	    /// A watcher observing any creature attacking.
128	    AttackWatch {
129	        watcher_id: ObjectId,
130	        watcher_card_id: CardId,
131	        controller: PlayerId,
132	        attacker_id: ObjectId,
133	        attacker_controller: PlayerId,
134	        description: String,
135	    },
136	    /// A creature's "when this deals combat damage to a creature" trigger.
137	    CombatDamageToCreature {
138	        creature_id: ObjectId,
139	        creature_card_id: CardId,
140	        controller: PlayerId,
141	        damaged_creature: ObjectId,
142	        amount: u32,
143	        description: String,
144	    },
145	    /// A creature's "when this becomes blocked" trigger (attacker that gets blocked).
146	    BecomesBlockedTrigger {
147	        object_id: ObjectId,
148	        card_id: CardId,
149	        controller: PlayerId,
150	        blocker_id: ObjectId,
151	        description: String,
152	    },
153	    /// A state-triggered ability (CR 603.8). These are checked during SBA processing
154	    /// and go on the stack like normal triggered abilities. The trigger won't fire again
155	    /// while it's already on the stack.
156	    StateTriggered {
157	        object_id: ObjectId,
158	        card_id: CardId,
159	        controller: PlayerId,
160	        description: String,
161	    },
162	}
163	
164	impl PendingTrigger {
165	    /// The player who controls this trigger.
166	    pub fn controller(&self) -> PlayerId {
167	        match self {
168	            PendingTrigger::SelfDies { controller, .. } => *controller,
169	            PendingTrigger::DeathWatch { controller, .. } => *controller,
170	            PendingTrigger::EnteredBattlefield { controller, .. } => *controller,
171	            PendingTrigger::EnterWatch { controller, .. } => *controller,
172	            PendingTrigger::CombatDamageToPlayer { controller, .. } => *controller,
173	            PendingTrigger::CombatDamageWatch { controller, .. } => *controller,
174	            PendingTrigger::DamageToPlayerWatch { controller, .. } => *controller,
175	            PendingTrigger::SpellCastWatch { controller, .. } => *controller,
176	            PendingTrigger::EndCombatTrigger { controller, .. } => *controller,
177	            PendingTrigger::UpkeepTrigger { controller, .. } => *controller,
178	            PendingTrigger::EndStepTrigger { controller, .. } => *controller,
179	            PendingTrigger::LeftBattlefield { .. } => PlayerId(255),
180	            PendingTrigger::AttacksTrigger { controller, .. } => *controller,
181	            PendingTrigger::BlocksTrigger { controller, .. } => *controller,
182	            PendingTrigger::AttackWatch { controller, .. } => *controller,
183	            PendingTrigger::CombatDamageToCreature { controller, .. } => *controller,
184	            PendingTrigger::BecomesBlockedTrigger { controller, .. } => *controller,
185	            PendingTrigger::StateTriggered { controller, .. } => *controller,
186	        }
187	    }
188	
189	    /// Display name for the stack view, including what the trigger does.
190	    pub fn display_name(&self, registry: &crate::cards::CardRegistry) -> String {
191	        let card_name = |card_id: CardId| {
192	            registry.card_data(card_id)
193	                .map(|d| d.name)
194	                .unwrap_or_else(|| "Unknown".into())
195	        };
196	        match self {
197	            PendingTrigger::SelfDies { dead_card_id, description, .. } => {
198	                if description.is_empty() {
199	                    format!("{}'s dies trigger", card_name(*dead_card_id))
200	                } else {
201	                    format!("{}'s dies trigger ({})", card_name(*dead_card_id), description)
202	                }
203	            }
204	            PendingTrigger::DeathWatch { watcher_card_id, description, .. } => {
205	                if description.is_empty() {
206	                    format!("{}'s triggered ability", card_name(*watcher_card_id))
207	                } else {
208	                    format!("{}'s triggered ability ({})", card_name(*watcher_card_id), description)
209	                }
210	            }
211	            PendingTrigger::EnteredBattlefield { card_id, description, .. } => {
212	                if description.is_empty() {
213	                    format!("{}'s ETB trigger", card_name(*card_id))
214	                } else {
215	                    format!("{}'s ETB trigger ({})", card_name(*card_id), description)
216	                }
217	            }
218	            PendingTrigger::EnterWatch { watcher_card_id, description, .. } => {
219	                if description.is_empty() {
220	                    format!("{}'s triggered ability", card_name(*watcher_card_id))
221	                } else {
222	                    format!("{}'s triggered ability ({})", card_name(*watcher_card_id), description)
223	                }
224	            }
225	            PendingTrigger::CombatDamageToPlayer { creature_card_id, description, .. } => {
226	                if description.is_empty() {
227	                    format!("{}'s combat damage trigger", card_name(*creature_card_id))
228	                } else {
229	                    format!("{}'s combat damage trigger ({})", card_name(*creature_card_id), description)
230	                }
231	            }
232	            PendingTrigger::CombatDamageWatch { watcher_card_id, description, .. }
233	            | PendingTrigger::DamageToPlayerWatch { watcher_card_id, description, .. } => {
234	                if description.is_empty() {
235	                    format!("{}'s triggered ability", card_name(*watcher_card_id))
236	                } else {
237	                    format!("{}'s triggered ability ({})", card_name(*watcher_card_id), description)
238	                }
239	            }
240	            PendingTrigger::SpellCastWatch { watcher_card_id, description, .. } => {
241	                if description.is_empty() {
242	                    format!("{}'s triggered ability", card_name(*watcher_card_id))
243	                } else {
244	                    format!("{}'s triggered ability ({})", card_name(*watcher_card_id), description)
245	                }
246	            }
247	            PendingTrigger::EndCombatTrigger { card_id, description, .. } => {
248	                if description.is_empty() {
249	                    format!("{}'s end of combat trigger", card_name(*card_id))
250	                } else {
251	                    format!("{}'s end of combat trigger ({})", card_name(*card_id), description)
252	                }
253	            }
254	            PendingTrigger::UpkeepTrigger { card_id, description, .. } => {
255	                if description.is_empty() {
256	                    format!("{}'s upkeep trigger", card_name(*card_id))
257	                } else {
258	                    format!("{}'s upkeep trigger ({})", card_name(*card_id), description)
259	                }
260	            }
261	            PendingTrigger::EndStepTrigger { card_id, description, .. } => {
262	                if description.is_empty() {
263	                    format!("{}'s end step trigger", card_name(*card_id))
264	                } else {
265	                    format!("{}'s end step trigger ({})", card_name(*card_id), description)
266	                }
267	            }
268	            PendingTrigger::LeftBattlefield { card_id, description, .. } => {
269	                if description.is_empty() {
270	                    format!("{}'s LTB trigger", card_name(*card_id))
271	                } else {
272	                    format!("{}'s LTB trigger ({})", card_name(*card_id), description)
273	                }
274	            }
275	            PendingTrigger::AttacksTrigger { card_id, description, .. }
276	            | PendingTrigger::AttackWatch { watcher_card_id: card_id, description, .. } => {
277	                if description.is_empty() {
278	                    format!("{}'s attack trigger", card_name(*card_id))
279	                } else {
280	                    format!("{}'s attack trigger ({})", card_name(*card_id), description)
281	                }
282	            }
283	            PendingTrigger::CombatDamageToCreature { creature_card_id, description, .. } => {
284	                if description.is_empty() {
285	                    format!("{}'s combat damage trigger", card_name(*creature_card_id))
286	                } else {
287	                    format!("{}'s combat damage trigger ({})", card_name(*creature_card_id), description)
288	                }
289	            }
290	            PendingTrigger::BlocksTrigger { card_id, description, .. }
291	            | PendingTrigger::BecomesBlockedTrigger { card_id, description, .. } => {
292	                if description.is_empty() {
293	                    format!("{}'s block trigger", card_name(*card_id))
294	                } else {
295	                    format!("{}'s block trigger ({})", card_name(*card_id), description)
296	                }
297	            }
298	            PendingTrigger::StateTriggered { card_id, description, .. } => {
299	                if description.is_empty() {
300	                    format!("{}'s state-triggered ability", card_name(*card_id))
301	                } else {
302	                    format!("{}'s state-triggered ability ({})", card_name(*card_id), description)
303	                }
304	            }
305	        }
306	    }
307	}
308	
309	/// Look up the description for a trigger from the card's TriggeredAbilityDef.
310	/// For transformed DFCs, also check the back face's triggered abilities.
311	fn trigger_description(registry: &CardRegistry, card_id: CardId, kind: &crate::cards::TriggerKind, is_transformed: bool) -> String {
312	    if let Some(behavior) = registry.get(card_id) {
313	        // Check front face triggers.
314	        if let Some(t) = behavior.card_data().triggered_abilities.iter().find(|t| &t.kind == kind) {
315	            return t.description.clone();
316	        }
317	        // For transformed DFCs, also check back face triggers.
318	        if is_transformed {
319	            if let Some(back) = behavior.back_face_data() {
320	                if let Some(t) = back.triggered_abilities.iter().find(|t| &t.kind == kind) {
321	                    return t.description.clone();
322	                }
323	            }
324	        }
325	    }
326	    String::new()
327	}
328	
329	/// Collect triggered abilities from events and add them to the stack
330	/// in APNAP order (active player first on bottom, non-active player on top).
331	///
332	/// Does NOT resolve them — the game loop resolves them one at a time,
333	/// giving players priority between each.
334	pub fn collect_triggers(state: &mut GameState, registry: &CardRegistry) {
335	    let events = state.events.clone();
336	    let start = state.trigger_event_index;
337	    let active_player = state.active_player;
338	
339	    let mut ap_triggers: Vec<PendingTrigger> = Vec::new();
340	    let mut nap_triggers: Vec<PendingTrigger> = Vec::new();
341	
342	    for (i, event) in events.iter().enumerate().skip(start) {
343	        match event {
344	            GameEvent::EnteredBattlefield { object, .. } => {
345	                let (card_id, controller) = match state.get_object(*object) {
346	                    Some(o) if o.zone == Zone::Battlefield => (o.card_id, o.controller),
347	                    _ => continue,
348	                };
349	                // Only collect if the card has an on_enter_battlefield handler.
350	                // Self ETB trigger.
351	                if registry.get(card_id).is_some() {
352	                    let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::EntersBattlefield, false);
353	                    let trigger = PendingTrigger::EnteredBattlefield {
354	                        object_id: *object,
355	                        card_id,
356	                        controller,
357	                        description: desc,
358	                    };
359	                    if controller == active_player {
360	                        ap_triggers.push(trigger);
361	                    } else {
362	                        nap_triggers.push(trigger);
363	                    }
364	                }
365	
366	                // ETB-watch: notify other permanents that a creature entered.
367	                if state.get_object(*object).map(|o| o.power.is_some()).unwrap_or(false) {
368	                    let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
369	                        .filter(|o| o.zone == Zone::Battlefield && o.id != *object)
370	                        .map(|o| (o.id, o.card_id, o.controller))
371	                        .collect();
372	                    for (watcher_id, watcher_card_id, watcher_controller) in watchers {
373	                        if registry.get(watcher_card_id).is_some() {
374	                            let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyCreatureEnters, false);
375	                            if !desc.is_empty() {
376	                                let trigger = PendingTrigger::EnterWatch {
377	                                    watcher_id,
378	                                    watcher_card_id,
379	                                    controller: watcher_controller,
380	                                    entered_id: *object,
381	                                    entered_controller: controller,
382	                                    description: desc,
383	                                };
384	                                if watcher_controller == active_player {
385	                                    ap_triggers.push(trigger);
386	                                } else {
387	                                    nap_triggers.push(trigger);
388	                                }
389	                            }
390	                        }
391	                    }
392	                }
393	            }
394	            GameEvent::CreatureDied { object, card_id, controller, damaged_by, last_known_toughness } => {
395	                let dead_id = *object;
396	                let dead_card_id = *card_id;
397	                let dead_controller = *controller;
398	                let dead_damaged_by = damaged_by.clone();
399	                let dead_toughness = *last_known_toughness;
400	
401	                // 1. Self-dies trigger.
402	                if registry.get(dead_card_id).is_some() {
403	                    let desc = trigger_description(registry, dead_card_id, &crate::cards::TriggerKind::SelfDies, false);
404	                    let trigger = PendingTrigger::SelfDies {
405	                        dead_id,
406	                        dead_card_id,
407	                        controller: dead_controller,
408	                        description: desc,
409	                    };
410	                    if dead_controller == active_player {
411	                        ap_triggers.push(trigger);
412	                    } else {
413	                        nap_triggers.push(trigger);
414	                    }
415	                }
416	
417	                // 2. Death-watch: collect triggers from all permanents on battlefield.
418	                let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
419	                    .filter(|o| o.zone == Zone::Battlefield && o.id != dead_id)
420	                    .map(|o| (o.id, o.card_id, o.controller))
421	                    .collect();
422	                for (watcher_id, watcher_card_id, watcher_controller) in watchers {
423	                    if registry.get(watcher_card_id).is_some() {
424	                        let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyCreatureDies, false);
425	                        let trigger = PendingTrigger::DeathWatch {
426	                            watcher_id,
427	                            watcher_card_id,
428	                            controller: watcher_controller,
429	                            dead_id,
430	                            dead_controller,
431	                            dead_damaged_by: dead_damaged_by.clone(),
432	                            dead_toughness,
433	                            description: desc,
434	                        };
435	                        if watcher_controller == active_player {
436	                            ap_triggers.push(trigger);
437	                        } else {
438	                            nap_triggers.push(trigger);
439	                        }
440	                    }
441	                }
442	            }
443	            GameEvent::LeftBattlefield { object, .. } => {
444	                let (card_id,) = match state.get_object(*object) {
445	                    Some(o) => (o.card_id,),
446	                    None => continue,
447	                };
448	                if registry.get(card_id).is_some() {
449	                    let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::LeavesBattlefield, false);
450	                    let trigger = PendingTrigger::LeftBattlefield {
451	                        object_id: *object,
452	                        card_id,
453	                        description: desc,
454	                    };
455	                    // LTB triggers go on AP side (they're usually self-referential).
456	                    ap_triggers.push(trigger);
457	                }
458	            }
459	            GameEvent::CombatDamageDealt { source, target, amount } => {
460	                // Creature-to-creature combat damage triggers.
461	                if let crate::events::DamageTarget::Object(damaged_id) = target {
462	                    let source_id = *source;
463	                    if let Some(obj) = state.get_object(source_id) {
464	                        if obj.zone == Zone::Battlefield && obj.power.is_some() {
465	                            let card_id = obj.card_id;
466	                            let controller = obj.controller;
467	                            if registry.get(card_id).is_some() {
468	                                let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::DealsCombatDamageToCreature, false);
469	                                if !desc.is_empty() {
470	                                    let trigger = PendingTrigger::CombatDamageToCreature {
471	                                        creature_id: source_id,
472	                                        creature_card_id: card_id,
473	                                        controller,
474	                                        damaged_creature: *damaged_id,
475	                                        amount: *amount,
476	                                        description: desc,
477	                                    };
478	                                    if controller == active_player {
479	                                        ap_triggers.push(trigger);
480	                                    } else {
481	                                        nap_triggers.push(trigger);
482	                                    }
483	                                }
484	                            }
485	                        }
486	                    }
